// Scaffolding generated by `dart run drift_dev make-migrations`; the
// data-integrity test below is hand-written. Add a test per new version.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:fundly/core/sync/synced_database.dart';

import 'generated/schema.dart';
import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;
import 'generated/schema_v3.dart' as v3;
import 'generated/schema_v4.dart' as v4;
import 'generated/schema_v5.dart' as v5;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // Verifies every possible upgrade produces exactly the saved schema.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = SyncedDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test('v1 to v2 keeps downloaded rows and adds an empty log', () async {
    const at = '2026-11-16 09:30:00+00';
    const types = [
      v1.CustomAccountTypesData(
        id: 't1',
        name: 'E-wallet',
        baseType: 'savingsCash',
        createdAt: at,
        updatedAt: at,
        revision: 2,
      ),
    ];
    const accounts = [
      v1.AccountsData(
        id: 'a1',
        name: 'GCash',
        type: 'savingsCash',
        openingBalanceMinor: 150000,
        currencyCode: 'PHP',
        isArchived: 0,
        customTypeId: 't1',
        isBudgetAccount: 1,
        createdAt: at,
        updatedAt: at,
        revision: 3,
      ),
    ];
    const categories = [
      v1.CategoriesData(
        id: 'c1',
        name: 'Fuel',
        kind: 'spending',
        isArchived: 0,
        isPlanArchived: 0,
        isPlanDeleted: 0,
        planGroup: 'spending',
        createdAt: at,
        updatedAt: at,
        revision: 1,
      ),
    ];
    const transactions = [
      v1.TransactionsData(
        id: 'x1',
        type: 'spending',
        amountMinor: 25000,
        currencyCode: 'PHP',
        date: '2026-11-20',
        payee: 'Shell',
        categoryId: 'c1',
        sourceAccountId: 'a1',
        note: '',
        createdAt: at,
        updatedAt: at,
        revision: 1,
      ),
    ];
    const plans = [
      v1.MonthlyPlansData(
        id: 'p1',
        month: '2026-11',
        categoryId: 'c1',
        targetAmountMinor: 300000,
        assignedAmountMinor: 200000,
        currencyCode: 'PHP',
        createdAt: at,
        updatedAt: at,
        revision: 4,
      ),
    ];

    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: SyncedDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insertAll(oldDb.customAccountTypes, types)
          ..insertAll(oldDb.accounts, accounts)
          ..insertAll(oldDb.categories, categories)
          ..insertAll(oldDb.transactions, transactions)
          ..insertAll(oldDb.monthlyPlans, plans);
      },
      validateItems: (newDb) async {
        List<Map<String, Object?>> json(Iterable<Insertable<Object>> rows) => [
          for (final row in rows)
            (row as dynamic).toJson() as Map<String, Object?>,
        ];
        expect(
          json(await newDb.select(newDb.customAccountTypes).get()),
          json(types),
        );
        expect(json(await newDb.select(newDb.accounts).get()), json(accounts));
        expect(
          json(await newDb.select(newDb.categories).get()),
          json(categories),
        );
        expect(
          json(await newDb.select(newDb.transactions).get()),
          json(transactions),
        );
        expect(json(await newDb.select(newDb.monthlyPlans).get()), json(plans));
        expect(await newDb.select(newDb.syncRejections).get(), isEmpty);
      },
    );
  });

  test('v2 to v3 keeps downloaded rows and refused changes, and adds empty '
      'space tables', () async {
    const at = '2026-11-24 09:30:00+00';
    const account = v2.AccountsData(
      id: 'a1',
      name: 'GCash',
      type: 'savingsCash',
      openingBalanceMinor: 150000,
      currencyCode: 'PHP',
      isArchived: 0,
      isBudgetAccount: 1,
      createdAt: at,
      updatedAt: at,
      revision: 3,
    );
    const category = v2.CategoriesData(
      id: 'c1',
      name: 'Fuel',
      kind: 'spending',
      isArchived: 0,
      isPlanArchived: 0,
      isPlanDeleted: 0,
      planGroup: 'spending',
      createdAt: at,
      updatedAt: at,
      revision: 1,
    );
    const rejection = v2.SyncRejectionsData(
      batchId: 'b1',
      kind: 'rejected',
      code: 'revision_conflict',
      operations: '{"version":1,"items":[]}',
      createdIds: '[]',
      labels: '{}',
      rejectedAt: '2026-11-24T01:00:00.000Z',
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 2,
      newVersion: 3,
      createOld: v2.DatabaseAtV2.new,
      createNew: v3.DatabaseAtV3.new,
      openTestedDatabase: SyncedDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insertAll(oldDb.accounts, [account])
          ..insertAll(oldDb.categories, [category])
          ..insertAll(oldDb.syncRejections, [rejection]);
      },
      validateItems: (newDb) async {
        Map<String, Object?> json(Object row) =>
            (row as dynamic).toJson() as Map<String, Object?>;
        expect((await newDb.select(newDb.accounts).get()).map(json), [
          json(account),
        ]);
        expect((await newDb.select(newDb.categories).get()).map(json), [
          json(category),
        ]);
        expect((await newDb.select(newDb.syncRejections).get()).map(json), [
          json(rejection),
        ]);
        expect(await newDb.select(newDb.spaces).get(), isEmpty);
        expect(await newDb.select(newDb.spaceMembers).get(), isEmpty);
      },
    );
  });

  test('v3 to v4 keeps spaces, members and the log; members gain an empty '
      'email and name', () async {
    const at = '2026-11-24 09:30:00+00';
    const space = v3.SpacesData(
      id: 's1',
      name: 'Household',
      createdBy: 'u1',
      createdAt: at,
      updatedAt: at,
      revision: 2,
    );
    const member = v3.SpaceMembersData(
      id: 'm1',
      spaceId: 's1',
      userId: 'u1',
      role: 'owner',
      createdAt: at,
      updatedAt: at,
    );
    const rejection = v3.SyncRejectionsData(
      batchId: 'b1',
      kind: 'rejected',
      code: 'revision_conflict',
      operations: '{"version":1,"items":[]}',
      createdIds: '[]',
      labels: '{}',
      rejectedAt: '2026-11-24T01:00:00.000Z',
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 3,
      newVersion: 4,
      createOld: v3.DatabaseAtV3.new,
      createNew: v4.DatabaseAtV4.new,
      openTestedDatabase: SyncedDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insertAll(oldDb.spaces, [space])
          ..insertAll(oldDb.spaceMembers, [member])
          ..insertAll(oldDb.syncRejections, [rejection]);
      },
      validateItems: (newDb) async {
        Map<String, Object?> json(Object row) =>
            (row as dynamic).toJson() as Map<String, Object?>;
        expect((await newDb.select(newDb.spaces).get()).map(json), [
          json(space),
        ]);
        expect((await newDb.select(newDb.spaceMembers).get()).map(json), [
          {...json(member), 'email': null, 'displayName': null},
        ]);
        expect((await newDb.select(newDb.syncRejections).get()).map(json), [
          json(rejection),
        ]);
      },
    );
  });

  test('v3 to v4 in a PowerSync store marks members for the next download '
      'to write again', () async {
    final schema = await verifier.schemaAt(3);
    // Stands in for PowerSync's table of rows to restore from its log.
    schema.rawDatabase
      ..execute(
        'CREATE TABLE ps_updated_rows (row_type TEXT, row_id TEXT, '
        'PRIMARY KEY (row_type, row_id))',
      )
      ..execute(
        'INSERT INTO space_members (id, space_id, user_id, role, created_at, '
        "updated_at) VALUES ('m1', 's1', 'u1', 'owner', 'x', 'x')",
      );
    final db = SyncedDatabase(schema.newConnection());
    await verifier.migrateAndValidate(db, 4);
    final marked = await db
        .customSelect('SELECT row_type, row_id FROM ps_updated_rows')
        .get();
    expect(
      [
        for (final row in marked)
          (row.read<String>('row_type'), row.read<String>('row_id')),
      ],
      [('space_members', 'm1')],
    );
    await db.close();
  });

  test('v4 to v5 keeps every category; none has a default Target', () async {
    const at = '2026-11-24 09:30:00+00';
    const account = v4.AccountsData(
      id: 'acc-card',
      name: 'RCBC Card',
      type: 'credit',
      openingBalanceMinor: 0,
      currencyCode: 'PHP',
      isArchived: 0,
      isBudgetAccount: 0,
      createdAt: at,
      updatedAt: at,
      revision: 1,
    );
    const categories = [
      v4.CategoriesData(
        id: 'cat-food',
        name: 'Food',
        kind: 'spending',
        isArchived: 0,
        isPlanArchived: 0,
        isPlanDeleted: 0,
        planGroup: 'savings',
        createdAt: at,
        updatedAt: at,
        revision: 3,
      ),
      v4.CategoriesData(
        id: 'cat-card',
        name: 'RCBC Card',
        kind: 'spending',
        isArchived: 0,
        isPlanArchived: 0,
        isPlanDeleted: 0,
        planGroup: 'liability',
        linkedAccountId: 'acc-card',
        createdAt: at,
        updatedAt: at,
        revision: 1,
      ),
    ];

    await verifier.testWithDataIntegrity(
      oldVersion: 4,
      newVersion: 5,
      createOld: v4.DatabaseAtV4.new,
      createNew: v5.DatabaseAtV5.new,
      openTestedDatabase: SyncedDatabase.new,
      createItems: (batch, oldDb) => batch
        ..insert(oldDb.accounts, account)
        ..insertAll(oldDb.categories, categories),
      validateItems: (newDb) async {
        final rows = await (newDb.select(
          newDb.categories,
        )..orderBy([(c) => OrderingTerm(expression: c.id)])).get();
        expect(rows.map((row) => row.toJson()).toList(), [
          for (final category in categories.reversed)
            {...category.toJson(), 'defaultTargetMinor': null},
        ]);
      },
    );
  });

  test('v4 to v5 in a PowerSync store marks categories for the next download '
      'to write again', () async {
    final schema = await verifier.schemaAt(4);
    schema.rawDatabase
      ..execute(
        'CREATE TABLE ps_updated_rows (row_type TEXT, row_id TEXT, '
        'PRIMARY KEY (row_type, row_id))',
      )
      ..execute(
        'INSERT INTO categories (id, name, kind, is_archived, '
        'is_plan_archived, is_plan_deleted, plan_group, created_at, '
        "updated_at, revision) VALUES ('c1', 'Food', 'spending', 0, 0, 0, "
        "'spending', 'x', 'x', 1)",
      );
    final db = SyncedDatabase(schema.newConnection());
    await verifier.migrateAndValidate(db, 5);
    final marked = await db
        .customSelect('SELECT row_type, row_id FROM ps_updated_rows')
        .get();
    expect(
      [
        for (final row in marked)
          (row.read<String>('row_type'), row.read<String>('row_id')),
      ],
      [('categories', 'c1')],
    );
    await db.close();
  });
}
